193: static pci_ers_result_t adf_slot_reset(struct pci_dev *pdev)
194: {
195: 	struct adf_accel_dev *accel_dev = adf_devmgr_pci_to_accel_dev(pdev);
196: 	int res = 0;
197: 
198: 	if (!accel_dev) {
199: 		pr_err("QAT: Can't find acceleration device\n");
200: 		return PCI_ERS_RESULT_DISCONNECT;
201: 	}
202: 
203: 	if (!pdev->is_busmaster)
204: 		pci_set_master(pdev);
205: 	pci_restore_state(pdev);
206: 	pci_save_state(pdev);
207: 	res = adf_dev_up(accel_dev, false);
208: 	if (res && res != -EALREADY)
209: 		return PCI_ERS_RESULT_DISCONNECT;
210: 
211: 	adf_reenable_sriov(accel_dev);
212: 	adf_pf2vf_notify_restarted(accel_dev);
213: 	adf_dev_restarted_notify(accel_dev);
214: 	clear_bit(ADF_STATUS_RESTARTING, &accel_dev->status);
215: 	return PCI_ERS_RESULT_RECOVERED;

